498	package net.officefloor.hq.app.setting;
499	
500	import java.math.BigDecimal;
501	import java.time.LocalDate;
502	import java.time.format.DateTimeParseException;
503	import java.util.ArrayList;
504	import java.util.List;
505	import java.util.regex.Pattern;
506	import net.officefloor.hq.app.role.Role;
507	import net.officefloor.hq.app.role.RoleStore;
508	import net.officefloor.hq.app.sheet.InvalidSheetException;
509	import net.officefloor.plugin.variable.Out;
510	import org.springframework.web.bind.annotation.PathVariable;
511	import org.springframework.web.bind.annotation.RequestBody;
512	
513	public class ValidateSetting {
514	    /** 0.00 or more, with up to two decimals. */
515	    private static final Pattern LIMIT = Pattern.compile("\\d+(\\.\\d{1,2})?");
516	    /** A whole number of days, 0 or more. */
517	    private static final Pattern DAYS = Pattern.compile("\\d{1,5}");
518	
519	    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody SettingRequest request, Out<SettingInput> body, RoleStore roles) throws InvalidSheetException {
520	        roles.refuseChange(sheetId.trim(), request == null ? null : request.user());
521	        String key = request == null || request.key() == null ? "" : request.key().trim();
522	        boolean floor = SettingStore.FLOOR.equals(key);
523	        boolean terms = SettingStore.TERMS.equals(key);
524	        boolean gradeTerms = key.startsWith(SettingStore.TERMS_PREFIX)
525	                && SettingStore.GRADES.contains(key.substring(SettingStore.TERMS_PREFIX.length()));
526	        boolean gradeGrace = SettingStore.isGradeGrace(key);
527	        boolean late = SettingStore.LATE_PCT.equals(key);
528	        boolean numbering = SettingStore.PERIOD_NUMBERING_FROM.equals(key);
529	        boolean entry = SettingStore.ENTRY_DATE.equals(key);
530	        boolean dated = SettingStore.POLICY_DATE.equals(key) || numbering || entry;
531	        boolean cap = SettingStore.CAP.equals(key);
532	        boolean gradeProof = SettingStore.isGradeProofThreshold(key);
533	        boolean proof = SettingStore.PROOF_THRESHOLD.equals(key) || gradeProof;
534	        boolean note = SettingStore.NOTE_THRESHOLD.equals(key);
535	        boolean pot = SettingStore.POT.equals(key);
536	        if (SettingStore.GRACE_DAYS.equals(key)) {
537	            String value = request.value() == null ? "" : request.value().trim();
538	            if (!value.isEmpty() && !DAYS.matcher(value).matches()) {
539	                throw new InvalidSheetException("The grace days must be a whole number of days, 0 or more, or blank");
540	            }
541	            body.set(new SettingInput(key, value.isEmpty() ? null : String.valueOf(Integer.parseInt(value)), null,
542	                    request.user()));
543	            return;
544	        }
545	        if (key.startsWith(SettingStore.PERM_PREFIX)
546	                && SettingStore.PERM_ACTIONS.contains(key.substring(SettingStore.PERM_PREFIX.length()))) {
547	            body.set(new SettingInput(key, perm(request.value()), null, request.user()));
548	            return;
549	        }
550	        if (!SettingStore.CLERK_LIMIT.equals(key) && !cap && !proof && !note && !pot && !floor && !terms && !gradeTerms && !gradeGrace && !late && !dated) {
551	            throw new InvalidSheetException("Not a setting: " + key);
552	        }
553	        String value = request.value() == null ? "" : request.value().trim();
554	        String fromValue = request.from() == null ? "" : request.from().trim();
555	        LocalDate from = null;
556	        if (!dated && !pot && !fromValue.isEmpty()) {
557	            try {
558	                from = LocalDate.parse(fromValue);
559	            } catch (DateTimeParseException e) {
560	                throw new InvalidSheetException("The from-date must be a date (YYYY-MM-DD), or blank");
561	            }
562	        }
563	        if (dated) {
564	            if (value.isEmpty()) {
565	                body.set(new SettingInput(key, null, from, request.user()));
566	                return;
567	            }
568	            try {
569	                body.set(new SettingInput(key, LocalDate.parse(value).toString(), from, request.user()));
570	            } catch (DateTimeParseException e) {
571	                throw new InvalidSheetException((numbering ? "The period numbering from" : entry ? "The entry date" : "The policy date")
572	                        + " must be a date (YYYY-MM-DD), or blank");
573	            }
574	            return;
575	        }
576	        if (gradeGrace) {
577	            if (value.isEmpty()) {
578	                body.set(new SettingInput(key, null, from, request.user()));
579	                return;
580	            }
581	            if (!DAYS.matcher(value).matches()) {
582	                throw new InvalidSheetException("The grade's grace days must be a whole number of days, 0 or more, or blank");
583	            }
584	            body.set(new SettingInput(key, String.valueOf(Integer.parseInt(value)), from, request.user()));
585	            return;
586	        }
587	        if (gradeTerms) {
588	            if (value.isEmpty()) {
589	                body.set(new SettingInput(key, null, from, request.user()));
590	                return;
591	            }
592	            if (!DAYS.matcher(value).matches()) {
593	                throw new InvalidSheetException("The grade's terms must be a whole number of days, 0 or more, or blank");
594	            }
595	            body.set(new SettingInput(key, String.valueOf(Integer.parseInt(value)), from, request.user()));
596	            return;
597	        }
598	        if (terms) {
599	            if (value.isEmpty()) {
600	                body.set(new SettingInput(key, String.valueOf(SettingStore.DEFAULT_TERMS), from, request.user()));
601	                return;
602	            }
603	            if (!DAYS.matcher(value).matches()) {
604	                throw new InvalidSheetException("The terms must be a whole number of days, 0 or more");
605	            }
606	            body.set(new SettingInput(key, String.valueOf(Integer.parseInt(value)), from, request.user()));
607	            return;
608	        }
609	        if (value.isEmpty() && floor) {
610	            body.set(new SettingInput(key, SettingStore.DEFAULT_FLOOR.toPlainString(), from, request.user()));
611	            return;
612	        }
613	        if (value.isEmpty() && late) {
614	            body.set(new SettingInput(key, SettingStore.DEFAULT_LATE_PCT.toPlainString(), from, request.user()));
615	            return;
616	        }
617	        if (value.isEmpty()) {
618	            body.set(new SettingInput(key, null, from, request.user()));
619	            return;
620	        }
621	        if (!LIMIT.matcher(value).matches()) {
622	            throw new InvalidSheetException(floor ? "The floor must be 0.00 or more with up to two decimals"
623	                    : late ? "The late percent must be 0.00 or more with up to two decimals"
624	                    : gradeProof ? "The grade's proof threshold must be 0.00 or more with up to two decimals, or blank"
625	                    : proof ? "The proof threshold must be 0.00 or more with up to two decimals, or blank"
626	                    : note ? "The note threshold must be 0.00 or more with up to two decimals, or blank"
627	                    : pot ? "The pot must be 0.00 or more with up to two decimals, or blank"
628	                    : cap ? "The cap must be 0.00 or more with up to two decimals, or blank"
629	                    : "The clerk limit must be 0.00 or more with up to two decimals, or blank");
630	        }
631	        body.set(new SettingInput(key, new BigDecimal(value).setScale(2).toPlainString(), from, request.user()));
632	    }
633	
634	    /** The roles listed, comma separated without spaces, or null when blank (the standing rule). */
635	    private static String perm(String raw) throws InvalidSheetException {
636	        String value = raw == null ? "" : raw.trim();
637	        if (value.isEmpty()) {
638	            return null;
639	        }
640	        List<String> roles = new ArrayList<>();
641	        for (String part : value.split(",")) {
642	            String role = part.trim();
643	            if (Role.of(role) == null || Role.of(role) == Role.VIEWER) {
644	                throw new InvalidSheetException("A permission lists roles (clerk, steward), comma separated, or is blank");
645	            }
646	            if (!roles.contains(role)) {
647	                roles.add(role);
648	            }
649	        }
650	        return String.join(",", roles);
651	    }
