# GET /api/sheets/{sheetId} — the sheet as the store holds it now. A sheet never loaded before is
# empty: there is nothing to create, everything else in the app is kept per sheet id.
respond:
  class: net.officefloor.hq.app.sheet.RespondWithSheet
package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import net.officefloor.hq.app.history.History;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

public class RespondWithSheet {
    public void respond(@PathVariable("sheetId") String sheetId,
            @RequestParam(name = "asOf", required = false) String asOf, SheetStore store,
            ObjectResponse<SheetResponse> response) {
        String id = sheetId.trim();
        LocalDate on = History.date(asOf);
        response.send(new SheetResponse(id, store.today(id).toString(),
                on == null ? store.archived(id) : store.archivedBy(id, on), on == null ? null : on.toString()));
    }
}
package net.officefloor.hq.app.sheet;

/** A sheet as the front end reads it. {@code today} is ISO yyyy-MM-dd; an archived sheet
 *  refuses every change. {@code asOf} (yyyy-MM-dd) is the date the screen shows the sheet as of, null when
 *  it shows it as it is now; {@code archived} is then whether it was archived by the end of that date. */
public record SheetResponse(String id, String today, boolean archived, String asOf) {
}
# POST /api/sheets/{sheetId}/settings — change a setting (body: {key, value, from, user}). The keys are
# clerk-limit: a number of 0.00 or more with up to two decimals, or blank for no limit; and floor: the
# least a claim's live due may be, 0.00 or more with up to two decimals, blank for its default 1.00; and
# terms: the whole days (0 or more) after its date a claim is due by, blank for its default 14; and
# terms-A, terms-B, terms-C: a grade's own terms, which a claim of a person of that grade (on the claim's
# date) takes instead, blank to use the sheet's terms (a claim's due-by is fixed when it is added); and
# late-pct: the percent of an overdue claim's figure charged per full 30 days overdue, 0.00 or more with
# up to two decimals, blank for its default 0.00; and cap: the most a person's due-total may be, 0.00 or
# more with up to two decimals, or blank for none; note-threshold: the due above which a claim needs a
# note before it is opened, 0.00 or more with up to two decimals, or blank for none; and proof-threshold: the due above which a claim needs a
# proof before it is settled or approved, 0.00 or more with up to two decimals, or blank for none; and
# proof-threshold-A, proof-threshold-B, proof-threshold-C: a grade's own proof threshold, which a claim of a
# person of that grade (on the claim's date) takes instead, blank for none (then the sheet's).
# Each of these is dated: its value is recorded from the from-date (yyyy-MM-dd, blank for the sheet's
# today), keeping the values recorded from other dates and replacing one recorded from the same date. A
# claim's floor, late percent, terms and proof threshold are those in force on its date; the clerk limit and cap those in
# force on the sheet's today. policy-date, period-numbering-from and entry-date are not dated (from is ignored);
# entry-date (yyyy-MM-dd, blank for off) is the default date of a new claim in place of the sheet's today.
# Any other key or value is refused (400) and nothing is stored. A stored change is recorded in the
# audit file as SETTING_CHANGED, ending from=<date> when a from-date was given (even when the value is the one already in force), then ROLLUP/TOTALS
# for the figures it moved; a refused one records nothing.
validate:
  class: net.officefloor.hq.app.setting.ValidateSetting
  next: snapshot
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.setting.SaveSetting
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.setting.AuditSettingChanged
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.setting.RespondWithSettings
  govern: [ transaction ]
-- A sheet's own settings. A sheet with no row here has never been changed: its today is the real date.
CREATE TABLE sheet (
    id    VARCHAR(255) PRIMARY KEY,
    today DATE NOT NULL
);
-- An archived sheet stays visible but refuses every change. Only a steward archives a sheet.
ALTER TABLE sheet ADD COLUMN archived BOOLEAN DEFAULT FALSE NOT NULL;
package net.officefloor.hq.app.history;

import java.time.LocalDate;
import java.util.Arrays;
import java.util.stream.Collectors;

/** Reads a table as it stood at the end of a date, from the versions {@link HistoryTrigger} keeps: each row's
 *  last version made while the sheet's today was on or before the date, unless that version deleted it. A
 *  change made while the sheet's today was after the date does not count, whenever it was made. */
public final class History {
    private History() {
    }

    /** The date of an {@code asOf} query parameter (yyyy-MM-dd): null when absent or blank, so the store is
     *  read as it is now. */
    public static LocalDate date(String asOf) {
        return asOf == null || asOf.isBlank() ? null : LocalDate.parse(asOf.trim());
    }

    /** A table expression, named as the table, for use in place of it in a query's FROM: the table's rows
     *  (each identified by {@code keys}, comma separated) as they stood at the end of {@code date}. */
    public static String asOf(String table, String keys, LocalDate date) {
        String on = "DATE '" + date + "'";
        String same = Arrays.stream(keys.split(",")).map(String::trim).map(k -> "l." + k + " = h." + k)
                .collect(Collectors.joining(" AND "));
        return "(SELECT h.* FROM " + table + "_hist h WHERE h.hist_made_on <= " + on + " AND NOT EXISTS (SELECT 1 FROM "
                + table + "_hist l WHERE " + same + " AND l.hist_made_on <= " + on + " AND l.hist_seq > h.hist_seq) AND NOT h.hist_gone) "
                + table;
    }
}
